// Generated from src/registry/sources/control-ui/recipes/table.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const tableKnobs = [
  "--cui-table-background",
  "--cui-table-foreground",
  "--cui-table-border-color",
  "--cui-table-row-hover-background",
  "--cui-table-row-selected-background",
  "--cui-table-header-foreground",
  "--cui-table-footer-background",
] as const;
export type TableKnobStyle = Partial<Record<(typeof tableKnobs)[number], string>>;

@layer components {
  :where([data-control-family="table"][data-slot="root"]) {
    --cui-table-background: transparent;
    --cui-table-foreground: var(--foreground);
    --cui-table-border-color: var(--border);
    --cui-table-footer-background: oklch(from var(--foreground) l c h / 0.03);
    --cui-table-header-foreground: var(--muted-foreground);
    --cui-table-row-hover-background: oklch(from var(--foreground) l c h / 0.03);
    --cui-table-row-selected-background: oklch(from var(--foreground) l c h / 0.05);
    background: var(--cui-table-background);
    color: var(--cui-table-foreground);
    border-collapse: collapse;
    font-size: var(--text-body);
  }

  :where([data-control-family="table"][data-slot="header"] [data-slot="row"]) {
    border-bottom-color: var(--cui-table-border-color);
  }

  :where([data-control-family="table"][data-slot="footer"]) {
    border-top-color: var(--cui-table-border-color);
    background: var(--cui-table-footer-background);
    border-top-style: solid;
    border-top-width: 1px;
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="table"][data-slot="row"]) {
    border-bottom-color: var(--cui-table-border-color);
    transition: background-color var(--duration-fast) var(--ease-standard);
    border-bottom-style: solid;
    border-bottom-width: 1px;
  }

  :where(
    [data-control-family="table"][data-slot="row"]:is(
      [data-interactive],
      [tabindex],
      [role="button"],
      :has(a, button, [role="checkbox"])
    ):hover
  ) {
    background: var(--cui-table-row-hover-background);
  }

  :where([data-control-family="table"][data-slot="row"][data-state="selected"]) {
    background: var(--cui-table-row-selected-background);
  }

  :where([data-control-family="table"][data-slot="head"]) {
    block-size: calc(var(--spacing) * 10);
    padding-inline: calc(var(--spacing) * 2);
    color: var(--cui-table-header-foreground);
    text-align: left;
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="table"][data-slot="caption"]) {
    margin-block-start: calc(var(--spacing) * 4);
    color: var(--muted-foreground);
    font-size: var(--text-body);
  }

  :where([data-control-family="table"][data-slot="footer"] > tr:last-child) {
    border-bottom-style: solid;
    border-bottom-width: 0px;
  }

  :where([data-control-family="table"][data-slot="body"] tr:last-child) {
    border-style: solid;
    border-width: 0px;
  }

  :where([data-control-family="table"][data-slot="header"] tr) {
    border-bottom-style: solid;
    border-bottom-width: 1px;
  }

  :where([data-control-family="table"][data-slot="cell"]) {
    padding: calc(var(--spacing) * 2);
  }
}

@property --cui-table-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

@property --cui-table-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-table-border-color {
